-- REVIEW ONLY: Owner approval required before Production application.
-- Exact approved registry metadata only. No source text, student records, publication or billing.
begin;
set local lock_timeout='5s';
set local statement_timeout='15s';
do $$begin
 if current_user<>'postgres' then raise exception 'OWNER_REQUIRED';end if;
 if to_regprocedure('public.essay_registered_questions(uuid)') is not null then raise exception 'REGISTRY_RPC_ALREADY_EXISTS';end if;
 if to_regprocedure('math_private.require_active(uuid[])') is null or not exists(select 1 from pg_roles where rolname='essay_worker') then raise exception 'EXISTING_RUNTIME_REQUIRED';end if;
end$$;
create function public.essay_registered_questions(p_subject uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
 -- Gateway supplies the online-verified, existing allowlisted Auth UID; students cannot call this RPC.
 perform math_private.require_active(array[p_subject]);
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'essay_exam_id',q.essay_exam_id,
 'question_key',q.question_key,'metadata_version',q.metadata_version,'is_published',q.is_published,
 'essay_exams',jsonb_build_object('university_id',e.university_id,'admission_year',e.admission_year,'exam_kind',e.exam_kind)) order by q.id),'[]'::jsonb)
 into result from public.essay_questions q join public.essay_exams e on e.id=q.essay_exam_id
